export function getOfficialRideImage(rideId: number | string, rideName?: string): string {
  if (TOGGI_RIDES_IMAGE_MAP[rideId]) return TOGGI_RIDES_IMAGE_MAP[rideId];
  const lower = (rideName || '').toLowerCase();
  if (lower.includes('work') || lower.includes('technical') || lower.includes('support') || lower.includes('maintenance')) {
    return "https://images.unsplash.com/photo-1581092160607-ee22621dd758?auto=format&fit=crop&w=600&q=80";
  }
  return "https://images.unsplash.com/photo-1511512578047-dfb367046420?auto=format&fit=crop&w=600&q=80";
}
